// A menu can pop down from a MainMenu or could be a pop out menu.
type Menu struct {
	Label string
	Items []*MenuItem
}

// NewMenu creates a new menu given the specified label (to show in a MainMenu) and list of items to display.
func NewMenu(label string, items ...*MenuItem) *Menu {
	return &Menu{Label: label, Items: items}
}

// Refresh updates the menu to reflect any changes to its items.
// This will update all windows that are currently displaying this menu.
//
// Since: 2.2
func (m *Menu) Refresh() {
	app := CurrentApp()
	if app == nil {
		return
	}

	for _, window := range app.Driver().AllWindows() {
		if mainMenu := window.MainMenu(); mainMenu != nil {
			// Trigger a refresh of the window to update the menu bar
			if content := window.Content(); content != nil {
				window.Canvas().Refresh(content)
			}
		}
	}
}

